#!/bin/bash
# Bootstrap nodestore using the runner auth token.
set -e

export AUTH_TOKEN={SECRET}
export AUTH_TARGET={ANCHOR}
export AUTH_ROLE=bootstrap-runner

echo "Bootstrapping nodestore for $AUTH_TARGET"
./run.sh

#!/bin/bash
# Daily backup runner.
set -euo pipefail

BACKEND_KEY={SECRET}
BACKEND_TARGET={ANCHOR}
BACKEND_OWNER=backup-cron

DATE=$(date +%Y-%m-%d)
echo "Backup $DATE -> $BACKEND_TARGET"
svc-cli backup --token "$BACKEND_KEY" --resource "$BACKEND_TARGET"

# Sentry self-hosted configuration overrides.
# Inlines the active internal service token so the bridge can run
# without a separate keystore mount.

from sentry.conf.server import *  # NOQA

DATABASES = {
    "default": {
        "ENGINE": "sentry.db.postgres",
        "NAME": "postgres",
        "USER": "postgres",
        "PASSWORD": "",
        "HOST": "postgres",
        "PORT": "5432",
    }
}

SENTRY_OPTIONS = {}
SENTRY_OPTIONS["service.options"] = {
    "api_token": "{SECRET}",
    "api_target": "{ANCHOR}",
    "api_owner": "service-bridge",
}
